#!/usr/bin/env python3
"""Adds the Android port to a checkout of ludovic111/horizon (run it in the repo's root folder).

    python3 android_port.py

It writes the new files, then edits Cargo.toml, game.rs, clipboard.rs and
horizon-client-input/Cargo.toml by matching exact text, so it keeps working while upstream moves;
if a piece of text is gone it stops before writing anything and says which one.
"""
import os, sys

NEW_FILES = {'.github/workflows/android.yml': 'name: Android APK\n\n# Builds an arm64 APK of Horizon with cargo-apk (docs/android.md). Run it by hand from the\n# Actions tab ("Run workflow"); the APK is the artifact `horizon-android-apk`.\non:\n  workflow_dispatch:\n  push:\n    branches: [android]\n\njobs:\n  apk:\n    runs-on: ubuntu-latest\n    timeout-minutes: 180\n    steps:\n      - uses: actions/checkout@v4\n\n      - uses: dtolnay/rust-toolchain@stable\n        with:\n          targets: aarch64-linux-android\n\n      - uses: Swatinem/rust-cache@v2\n        with:\n          key: android\n\n      - name: Android SDK and NDK paths\n        run: |\n          echo "ANDROID_NDK_ROOT=${ANDROID_NDK_LATEST_HOME}" >> "$GITHUB_ENV"\n          echo "ANDROID_NDK_HOME=${ANDROID_NDK_LATEST_HOME}" >> "$GITHUB_ENV"\n          echo "ANDROID_HOME=${ANDROID_SDK_ROOT:-$ANDROID_HOME}" >> "$GITHUB_ENV"\n\n      - name: Install cargo-apk\n        run: cargo install cargo-apk --locked\n\n      - name: Signing key (a throwaway one, the APK is for sideloading)\n        run: |\n          keytool -genkey -v -keystore "$HOME/horizon.keystore" -storepass android \\\n            -alias horizon -keypass android -keyalg RSA -keysize 2048 -validity 10000 \\\n            -dname "CN=Horizon,O=Horizon,C=US"\n          echo "CARGO_APK_RELEASE_KEYSTORE=$HOME/horizon.keystore" >> "$GITHUB_ENV"\n          echo "CARGO_APK_RELEASE_KEYSTORE_PASSWORD=android" >> "$GITHUB_ENV"\n\n      - name: Build the APK\n        run: cargo apk build --release -p horizon-android\n\n      - uses: actions/upload-artifact@v4\n        with:\n          name: horizon-android-apk\n          path: target/release/apk/*.apk\n          if-no-files-found: error\n', 'crates/horizon-android/Cargo.toml': '[package]\nname = "horizon-android"\nversion = "0.1.0"\nedition.workspace = true\nlicense.workspace = true\nrust-version = "1.90"\ndescription = "Horizon for Android: the client\'s game loop as a shared library (build with cargo-apk, see docs/android.md)"\n\n[lib]\nname = "horizon_android"\n# The root is in horizon-client/src so the game\'s modules (`mod game;`) sit where main.rs finds them.\npath = "../horizon-client/src/android_lib.rs"\ncrate-type = ["cdylib"]\n\n[dependencies]\nhorizon-client = { path = "../horizon-client", default-features = false }\nandroid-activity = { version = "0.6", features = ["native-activity"] }\nhorizon-assets = { path = "../horizon-assets" }\nhorizon-client-core = { path = "../horizon-client-core" }\nhorizon-client-input = { path = "../horizon-client-input" }\nhorizon-client-render = { path = "../horizon-client-render" }\nhorizon-command = { path = "../horizon-command" }\nhorizon-items = { path = "../horizon-items" }\nhorizon-core = { path = "../horizon-core" }\n# The server thread ahead of the workers (MinecraftServer.spin\'s Thread.setPriority).\nhorizon-threads = { path = "../horizon-threads" }\nhorizon-hdr = { path = "../horizon-hdr" }\nhorizon-world = { path = "../horizon-world" }\nhorizon-protocol = { path = "../horizon-protocol" }\n# server.properties, eula.txt and the user lists, shared with horizon-server.\nhorizon-server-files = { path = "../horizon-server-files" }\n# Shader packs: reading them and turning their GLSL into naga modules.\nhorizon-shaders = { path = "../horizon-shaders" }\n# Horizon\'s own shader packs: the format, the stages and the check (docs/shaders.md).\nhorizon-shader-api = { path = "../horizon-shader-api" }\nhorizon-friends = { path = "../horizon-friends" }\n# Horizon mods: sandboxed WebAssembly components, off unless installed and turned on (docs/mods.md).\n# Their runtime is the `mods` feature.\nhorizon-mods = { path = "../horizon-mods", default-features = false, features = ["index"] }\nwgpu = { version = "30.0.1", default-features = false, features = ["std", "parking_lot", "vulkan", "metal", "wgsl", "naga-ir"] }\nwinit = { version = "0.30.13", features = ["android-native-activity"] }\npollster = "0.4"\nbytemuck = { version = "1.24", features = ["derive"] }\nglam = "0.30"\npng = "0.18"\nsha2 = "0.10.9"\n# Server resource packs are checked and cached by their SHA-1, as vanilla does.\nsha1 = "0.10"\nserde = { version = "1", features = ["derive"] }\nserde_json = { version = "1.0.151", features = ["raw_value"] }\n# hlsl-out: the gfx.rs tests translate every shader as wgpu\'s DirectX 12 backend does. A normal feature,\n# not a dev-dependency\'s, so builds, tests and examples share one build of naga, wgpu and this crate.\nnaga = { version = "30.0.1", features = ["wgsl-in", "hlsl-out"] }\nminiz_oxide = "0.8"\nab_glyph = "0.2.32"\nlog = "0.4"\nchrono = { version = "0.4.42", default-features = false, features = ["clock", "std"] }\nflate2 = { version = "1.1.10", default-features = false, features = ["zlib-rs", "runtime_detection"] }\nhorizon-theme = { path = "../horizon-theme" }\n# Opt-in data collection: the game keeps, the launcher sends (docs/telemetry.md); `live` is\n# the anonymous "I\'m playing" ping the game sends itself (`heartbeat.rs`).\nhorizon-telemetry = { path = "../horizon-telemetry", default-features = false, features = ["live"] }\nhorizon-bench = { path = "../horizon-bench" }\nzip = { version = "2", default-features = false, features = ["deflate"] }\n# Controllers (evdev + libudev on Linux, IOKit on macOS, Windows.Gaming.Input); the `controllers` feature.\n# The DualSense\'s rumble, adaptive triggers and lights over HID (gilrs only reads it).\n# HTTPS to the Minecraft services (online-mode session join).\nureq = { version = "2", default-features = false, features = ["tls"] }\nunicode-bidi = "0.3.18"\n\n[features]\n# Off here: the game\'s `cfg(feature = ...)` switches. Code mods need wasmtime, controllers need evdev.\ncontrollers = []\nmods = []\n\n[lints]\nworkspace = true\n\n[package.metadata.android]\npackage = "io.horizon.game"\napk_name = "Horizon"\nbuild_targets = ["aarch64-linux-android"]\n\n[package.metadata.android.sdk]\nmin_sdk_version = 28\ntarget_sdk_version = 34\n\n[package.metadata.android.application]\nlabel = "Horizon"\n\n[package.metadata.android.application.activity]\norientation = "landscape"\nconfig_changes = "orientation|keyboardHidden|screenSize|smallestScreenSize|screenLayout|density|uiMode"\n\n[[package.metadata.android.uses_permission]]\nname = "android.permission.INTERNET"\n\n[[package.metadata.android.uses_feature]]\nname = "android.hardware.vulkan.level"\nversion = 1\nrequired = false\n', 'crates/horizon-client/src/android_lib.rs': '//! Horizon for Android: the same game loop as `main.rs`, built as the shared library the system\n//! loads (`crates/horizon-android`, docs/android.md). The activity is `android_activity`\'s native\n//! activity; winit makes the window from it.\n// Off Android nothing calls into the game: the crate only exists for `cargo-apk`.\n#![allow(dead_code, unused_imports, unused_variables)]\nmod game;\n\n/// Where the system\'s `Activity` starts the game: the app\'s files folder (the one a file manager\n/// reaches, `Android/data/<package>/files`) is the game home, and the prepared resources are its\n/// `resources` folder.\n#[cfg(target_os = "android")]\n#[unsafe(no_mangle)]\nfn android_main(app: android_activity::AndroidApp) {\n    use horizon_client::{crash, logging};\n\n    let home = app\n        .external_data_path()\n        .or_else(|| app.internal_data_path())\n        .unwrap_or_else(|| std::path::PathBuf::from("."));\n    // SAFETY: the first thing the program does, before any other thread reads the environment.\n    unsafe {\n        std::env::set_var("HORIZON_HOME", &home);\n        if std::env::var_os("HORIZON_RESOURCES").is_none_or(|r| r.is_empty()) {\n            std::env::set_var("HORIZON_RESOURCES", home.join("resources"));\n        }\n    }\n    let _ = game::ANDROID_APP.set(app);\n\n    horizon_client::telemetry::mark_start();\n    let home = logging::game_home();\n    logging::init(&home, "Render thread");\n    log::info!("Horizon {}", crash::version());\n    crash::install(home.clone(), "client");\n    if let Err(error) = game::run() {\n        log::error!("Horizon: {error}");\n        crash::report_error(&home, "client", &*error);\n    }\n    logging::flush();\n}\n', 'crates/horizon-client/src/game/touch.rs': '//! Touch controls (Android): the left side of the screen is a floating joystick, the right side\n//! turns the camera (a tap attacks, a long press mines), the round buttons jump, sneak, use,\n//! open the inventory and pause, and a tap on the hotbar picks a slot. Over any other screen a\n//! finger is the mouse: the touch becomes a cursor move and a left click.\n//!\n//! Nothing here is specific to Android, so it builds (and can be tried with a touch screen) on\n//! every platform; the Android entry point is what makes the game use it.\nuse super::*;\nuse std::cell::RefCell;\nuse winit::event::{Touch, TouchPhase};\n\n/// Finger travel (physical pixels) below which a touch still counts as a tap or a hold.\nconst SLOP: f32 = 16.0;\n/// A touch that lifts within this many milliseconds is a tap: one attack.\nconst TAP_MS: u128 = 250;\n/// A touch that stays put this many milliseconds starts mining (holds the attack button).\nconst HOLD_MS: u128 = 380;\n/// Camera turn per pixel of finger travel, in the units of a mouse\'s raw counts.\nconst LOOK_SENSITIVITY: f64 = 0.55;\n/// Frames a tap\'s attack stays pressed, so the game\'s per-frame input reads it.\nconst TAP_FRAMES: u8 = 3;\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum TouchButton {\n    Jump,\n    Use,\n    Sneak,\n    Inventory,\n    Pause,\n}\n\nstruct Stick {\n    id: u64,\n    origin: (f32, f32),\n}\n\nstruct Look {\n    id: u64,\n    start: (f32, f32),\n    last: (f32, f32),\n    at: Instant,\n    moved: bool,\n    mining: bool,\n}\n\n#[derive(Default)]\nstruct TouchState {\n    stick: Option<Stick>,\n    look: Option<Look>,\n    /// Fingers resting on a button.\n    buttons: Vec<(u64, TouchButton)>,\n    /// Frames until a tap\'s attack is released (0: none pending).\n    release_attack_in: u8,\n}\n\nthread_local! {\n    static STATE: RefCell<TouchState> = RefCell::new(TouchState::default());\n}\n\n/// The radius of the round buttons, and the joystick\'s reach, from the window height.\nfn unit(h: f32) -> f32 {\n    h * 0.075\n}\n\n/// Every button\'s centre and radius in physical pixels, and its label.\nfn layout(w: f32, h: f32) -> [(TouchButton, f32, f32, f32, &\'static str); 5] {\n    let r = unit(h);\n    [\n        (TouchButton::Jump, w - 2.4 * r, h - 2.6 * r, r * 1.15, "JUMP"),\n        (TouchButton::Use, w - 5.6 * r, h - 1.8 * r, r, "USE"),\n        (TouchButton::Sneak, w - 2.4 * r, h - 5.4 * r, r * 0.9, "SNK"),\n        (TouchButton::Inventory, w - 2.0 * r, 1.6 * r, r * 0.9, "INV"),\n        (TouchButton::Pause, w - 5.0 * r, 1.6 * r, r * 0.9, "ESC"),\n    ]\n}\n\nfn button_at(w: f32, h: f32, pos: (f32, f32)) -> Option<TouchButton> {\n    layout(w, h).into_iter().find_map(|(button, cx, cy, r, _)| {\n        let (dx, dy) = (pos.0 - cx, pos.1 - cy);\n        (dx * dx + dy * dy <= r * r * 1.44).then_some(button)\n    })\n}\n\nconst DIGITS: [KeyCode; 9] = [\n    KeyCode::Digit1,\n    KeyCode::Digit2,\n    KeyCode::Digit3,\n    KeyCode::Digit4,\n    KeyCode::Digit5,\n    KeyCode::Digit6,\n    KeyCode::Digit7,\n    KeyCode::Digit8,\n    KeyCode::Digit9,\n];\n\n/// The hotbar slot under a touch, from the vanilla layout: 182 gui pixels wide and 22 high at the\n/// bottom centre, a slot every 20 pixels after a 3 pixel border.\nfn hotbar_slot(w: f32, h: f32, pos: (f32, f32)) -> Option<usize> {\n    let scale = HudBatch::new([w as u32, h as u32]).scale;\n    let (gw, gh) = (w / scale, h / scale);\n    let (x, y) = (pos.0 / scale, pos.1 / scale);\n    if y < gh - 24.0 {\n        return None;\n    }\n    let slot = ((x - (gw / 2.0 - 91.0 + 3.0)) / 20.0).floor();\n    (0.0..9.0).contains(&slot).then_some(slot as usize)\n}\n\nimpl Game<\'_> {\n    /// Whether touches steer the player (the world is showing and the pointer is taken)\n    /// rather than act as a mouse over a screen.\n    pub(super) fn touch_playing(&self) -> bool {\n        self.captured && self.screen == Screen::Playing && self.title.is_none()\n    }\n\n    fn touch_window_id(&self) -> Option<WindowId> {\n        self.window.as_ref().map(|w| w.id())\n    }\n\n    fn touch_mouse(\n        &mut self,\n        event_loop: &ActiveEventLoop,\n        device_id: DeviceId,\n        button: MouseButton,\n        pressed: bool,\n    ) {\n        let Some(id) = self.touch_window_id() else {\n            return;\n        };\n        let state = if pressed {\n            ElementState::Pressed\n        } else {\n            ElementState::Released\n        };\n        self.window_event(\n            event_loop,\n            id,\n            WindowEvent::MouseInput {\n                device_id,\n                state,\n                button,\n            },\n        );\n    }\n\n    /// Lets go of everything a finger was holding: when a screen opens over the world, or\n    /// the window loses focus.\n    pub(super) fn touch_reset(&mut self) {\n        let (stick, buttons) = STATE.with(|s| {\n            let mut s = s.borrow_mut();\n            let had = s.stick.take().is_some();\n            s.look = None;\n            s.release_attack_in = 0;\n            (had, std::mem::take(&mut s.buttons))\n        });\n        if stick {\n            self.touch_stick_keys(0.0, 0.0, 1.0);\n        }\n        for (_, button) in buttons {\n            self.touch_button(None, button, false);\n        }\n    }\n\n    /// W, A, S and D from how far the joystick is pushed (`reach` is its full travel).\n    fn touch_stick_keys(&mut self, dx: f32, dy: f32, reach: f32) {\n        let dead = reach * 0.25;\n        for (code, on) in [\n            (KeyCode::KeyW, dy < -dead),\n            (KeyCode::KeyS, dy > dead),\n            (KeyCode::KeyA, dx < -dead),\n            (KeyCode::KeyD, dx > dead),\n        ] {\n            if on {\n                self.keys.insert(code);\n            } else {\n                self.keys.remove(&code);\n            }\n        }\n        // Pushed all the way forward: run.\n        if dy < -reach * 1.1 {\n            self.keys.insert(KeyCode::ControlLeft);\n        } else {\n            self.keys.remove(&KeyCode::ControlLeft);\n        }\n    }\n\n    fn touch_button(\n        &mut self,\n        pointer: Option<(&ActiveEventLoop, DeviceId)>,\n        button: TouchButton,\n        pressed: bool,\n    ) {\n        let key = match button {\n            TouchButton::Jump => Some(KeyCode::Space),\n            TouchButton::Sneak => Some(KeyCode::ShiftLeft),\n            TouchButton::Inventory => Some(KeyCode::KeyE),\n            TouchButton::Pause => Some(KeyCode::Escape),\n            TouchButton::Use => None,\n        };\n        if let Some(key) = key {\n            let _ = self.mapped_key(key, pressed, false);\n        } else if let Some((event_loop, device_id)) = pointer {\n            self.touch_mouse(event_loop, device_id, MouseButton::Right, pressed);\n        }\n    }\n\n    /// A finger touched, moved or lifted.\n    pub(super) fn touch_event(&mut self, event_loop: &ActiveEventLoop, touch: Touch) {\n        let Some(size) = self.window.as_ref().map(|w| w.inner_size()) else {\n            return;\n        };\n        let (w, h) = (size.width as f32, size.height as f32);\n        let pos = (touch.location.x as f32, touch.location.y as f32);\n\n        if !self.touch_playing() {\n            self.touch_reset();\n            self.touch_as_mouse(event_loop, &touch);\n            return;\n        }\n        let reach = unit(h) * 2.2;\n        match touch.phase {\n            TouchPhase::Started => {\n                if let Some(button) = button_at(w, h, pos) {\n                    STATE.with(|s| s.borrow_mut().buttons.push((touch.id, button)));\n                    self.touch_button(Some((event_loop, touch.device_id)), button, true);\n                } else if let Some(slot) = hotbar_slot(w, h, pos) {\n                    let _ = self.mapped_key(DIGITS[slot], true, false);\n                    let _ = self.mapped_key(DIGITS[slot], false, false);\n                } else if pos.0 < w * 0.45 {\n                    STATE.with(|s| {\n                        let mut s = s.borrow_mut();\n                        if s.stick.is_none() {\n                            s.stick = Some(Stick {\n                                id: touch.id,\n                                origin: pos,\n                            });\n                        }\n                    });\n                } else {\n                    STATE.with(|s| {\n                        let mut s = s.borrow_mut();\n                        if s.look.is_none() {\n                            s.look = Some(Look {\n                                id: touch.id,\n                                start: pos,\n                                last: pos,\n                                at: Instant::now(),\n                                moved: false,\n                                mining: false,\n                            });\n                        }\n                    });\n                }\n            }\n            TouchPhase::Moved => {\n                let stick = STATE.with(|s| {\n                    s.borrow()\n                        .stick\n                        .as_ref()\n                        .filter(|st| st.id == touch.id)\n                        .map(|st| st.origin)\n                });\n                if let Some(origin) = stick {\n                    self.touch_stick_keys(pos.0 - origin.0, pos.1 - origin.1, reach);\n                    return;\n                }\n                let delta = STATE.with(|s| {\n                    let mut s = s.borrow_mut();\n                    let look = s.look.as_mut().filter(|l| l.id == touch.id)?;\n                    let delta = (pos.0 - look.last.0, pos.1 - look.last.1);\n                    look.last = pos;\n                    let (tx, ty) = (pos.0 - look.start.0, pos.1 - look.start.1);\n                    if tx * tx + ty * ty > SLOP * SLOP {\n                        look.moved = true;\n                    }\n                    Some(delta)\n                });\n                if let Some((dx, dy)) = delta {\n                    // MouseHandler.onMove with the pointer grabbed; applied once per frame.\n                    self.mouse.on_move(\n                        0.0,\n                        0.0,\n                        f64::from(dx) * LOOK_SENSITIVITY,\n                        f64::from(dy) * LOOK_SENSITIVITY,\n                        true,\n                        true,\n                    );\n                    self.last_input = Instant::now();\n                }\n            }\n            TouchPhase::Ended | TouchPhase::Cancelled => {\n                let ended_stick = STATE.with(|s| {\n                    let mut s = s.borrow_mut();\n                    if s.stick.as_ref().is_some_and(|st| st.id == touch.id) {\n                        s.stick = None;\n                        true\n                    } else {\n                        false\n                    }\n                });\n                if ended_stick {\n                    self.touch_stick_keys(0.0, 0.0, reach);\n                    return;\n                }\n                let released = STATE.with(|s| {\n                    let mut s = s.borrow_mut();\n                    let at = s.buttons.iter().position(|(id, _)| *id == touch.id)?;\n                    Some(s.buttons.remove(at).1)\n                });\n                if let Some(button) = released {\n                    self.touch_button(Some((event_loop, touch.device_id)), button, false);\n                    return;\n                }\n                let look = STATE.with(|s| {\n                    let mut s = s.borrow_mut();\n                    if s.look.as_ref().is_some_and(|l| l.id == touch.id) {\n                        s.look.take()\n                    } else {\n                        None\n                    }\n                });\n                if let Some(look) = look {\n                    if look.mining {\n                        self.touch_mouse(event_loop, touch.device_id, MouseButton::Left, false);\n                    } else if !look.moved\n                        && touch.phase == TouchPhase::Ended\n                        && look.at.elapsed().as_millis() <= TAP_MS\n                    {\n                        self.touch_mouse(event_loop, touch.device_id, MouseButton::Left, true);\n                        STATE.with(|s| s.borrow_mut().release_attack_in = TAP_FRAMES);\n                    }\n                }\n            }\n        }\n    }\n\n    /// Over a screen: the touch moves the cursor, and a press and a lift are a left click.\n    fn touch_as_mouse(&mut self, event_loop: &ActiveEventLoop, touch: &Touch) {\n        let Some(id) = self.touch_window_id() else {\n            return;\n        };\n        self.window_event(\n            event_loop,\n            id,\n            WindowEvent::CursorMoved {\n                device_id: touch.device_id,\n                position: touch.location,\n            },\n        );\n        match touch.phase {\n            TouchPhase::Started => {\n                self.touch_mouse(event_loop, touch.device_id, MouseButton::Left, true)\n            }\n            TouchPhase::Ended | TouchPhase::Cancelled => {\n                self.touch_mouse(event_loop, touch.device_id, MouseButton::Left, false)\n            }\n            TouchPhase::Moved => {}\n        }\n    }\n\n    /// Once per event loop turn: starts mining under a finger that stayed put, and lets go of a\n    /// tap\'s attack.\n    pub(super) fn touch_tick(&mut self, event_loop: &ActiveEventLoop) {\n        let Some(device_id) = self.touch_device_id() else {\n            return;\n        };\n        let (start_mining, release) = STATE.with(|s| {\n            let mut s = s.borrow_mut();\n            let mut start = false;\n            if let Some(look) = s.look.as_mut()\n                && !look.mining\n                && !look.moved\n                && look.at.elapsed().as_millis() >= HOLD_MS\n            {\n                look.mining = true;\n                start = true;\n            }\n            let mut release = false;\n            if s.release_attack_in > 0 {\n                s.release_attack_in -= 1;\n                release = s.release_attack_in == 0;\n            }\n            (start, release)\n        });\n        if start_mining {\n            self.touch_mouse(event_loop, device_id, MouseButton::Left, true);\n        }\n        if release {\n            self.touch_mouse(event_loop, device_id, MouseButton::Left, false);\n        }\n    }\n\n    /// `DeviceId` for the events the touch layer sends itself. winit only hands out a real one\n    /// with an event, so the last touch\'s is kept.\n    fn touch_device_id(&self) -> Option<DeviceId> {\n        LAST_DEVICE.with(|d| d.get())\n    }\n\n    /// Draws the buttons, the joystick and the hotbar\'s touch border over the world.\n    pub(super) fn draw_touch_controls(&self, batch: &mut HudBatch) {\n        let scale = batch.scale;\n        let (w, h) = (batch.width * scale, batch.height * scale);\n        let atlas = &self.gui.atlas;\n        let held: Vec<TouchButton> =\n            STATE.with(|s| s.borrow().buttons.iter().map(|(_, b)| *b).collect());\n        for (button, cx, cy, r, label) in layout(w, h) {\n            let alpha = if held.contains(&button) { 150 } else { 70 };\n            let half = r / scale;\n            batch.fill(\n                atlas,\n                cx / scale - half,\n                cy / scale - half,\n                half * 2.0,\n                half * 2.0,\n                rgba(255, 255, 255, alpha),\n            );\n            let text_w = label.len() as f32 * 6.0;\n            batch.text(\n                atlas,\n                label,\n                cx / scale - text_w / 2.0,\n                cy / scale - 4.0,\n                u32::MAX,\n                true,\n            );\n        }\n        let stick = STATE.with(|s| s.borrow().stick.as_ref().map(|st| st.origin));\n        if let Some((ox, oy)) = stick {\n            let half = unit(h) * 2.2 / scale;\n            batch.fill(\n                atlas,\n                ox / scale - half,\n                oy / scale - half,\n                half * 2.0,\n                half * 2.0,\n                rgba(255, 255, 255, 40),\n            );\n        }\n    }\n}\n\nthread_local! {\n    static LAST_DEVICE: std::cell::Cell<Option<DeviceId>> = const { std::cell::Cell::new(None) };\n}\n\n/// Remembers a touch\'s device so the touch layer can send events of its own.\npub(super) fn note_device(device_id: DeviceId) {\n    LAST_DEVICE.with(|d| d.set(Some(device_id)));\n}\n', 'docs/android.md': '# Horizon on Android (experimental)\n\nA touch build of the client for arm64 phones. It uses wgpu\'s Vulkan backend (OpenGL ES as a fallback),\nwinit\'s native-activity backend and the touch controls in `crates/horizon-client/src/game/touch.rs`.\nAudio and controllers are off; code mods are off.\n\n## Build\n\nRun the **Android APK** workflow (Actions tab, "Run workflow"), or on a machine with the Android NDK:\n\n    rustup target add aarch64-linux-android\n    cargo install cargo-apk --locked\n    cargo apk build --release -p horizon-android\n\nThe APK is in `target/release/apk/`.\n\n## Resources\n\nHorizon ships none of Mojang\'s files. Prepare them on a computer with `horizon-prepare` (docs/README),\nthen copy the folder `.local/horizon-client/<version>` to the phone as\n\n    Android/data/io.horizon.game/files/resources\n\n(the folder holding `horizon-resources.json`). Saves, options and logs go in the same `files` folder.\n\n## Controls\n\nLeft half of the screen: a floating joystick (push all the way forward to run). Right half: drag to\nlook, tap to attack, hold to mine. Buttons: JUMP, USE (place/use item), SNK (sneak), INV, ESC.\nTap the hotbar to pick a slot. Over menus a finger is the mouse. There is no on-screen keyboard yet,\nso chat and text fields cannot be typed in.\n'}
CLIPBOARD_STUB = '/// Android has no arboard: this stands in for it, so text copied in the game can still be pasted in\n/// the game (`SystemClipboard` keeps the last copy).\n#[cfg(target_os = "android")]\nmod arboard {\n    pub struct Clipboard;\n    #[derive(Debug)]\n    pub enum Error {\n        ContentNotAvailable,\n        Unavailable,\n    }\n    impl Clipboard {\n        pub fn new() -> Result<Self, Error> {\n            Err(Error::Unavailable)\n        }\n        pub fn get_text(&mut self) -> Result<String, Error> {\n            Err(Error::ContentNotAvailable)\n        }\n        pub fn set_text(&mut self, _text: String) -> Result<(), Error> {\n            Ok(())\n        }\n    }\n}\n\n'

GAME_EDIT = '\ndef once(old, new, count=1):\n    global s\n    n = s.count(old)\n    assert n == count, f"expected {count} match(es), got {n} for: {old[:70]!r}"\n    s = s.replace(old, new)\n\nonce("mod allays;\\n", "mod allays;\\nmod touch;\\n")\n\nonce("EventLoop::new()?.run_app(", "new_event_loop()?.run_app(", count=2)\nonce("fn run_event_loop(mut game: Game<\'_>) -> Result<()> {",\n\'\'\'#[cfg(target_os = "android")]\npub static ANDROID_APP: std::sync::OnceLock<android_activity::AndroidApp> =\n    std::sync::OnceLock::new();\n\n#[cfg(not(target_os = "android"))]\nfn new_event_loop() -> Result<EventLoop<()>> {\n    Ok(EventLoop::new()?)\n}\n\n/// Android\'s event loop is made from the app the system started.\n#[cfg(target_os = "android")]\nfn new_event_loop() -> Result<EventLoop<()>> {\n    use winit::platform::android::EventLoopBuilderExtAndroid;\n    let app = ANDROID_APP\n        .get()\n        .ok_or("the Android app was not set before the game started")?\n        .clone();\n    Ok(EventLoop::builder().with_android_app(app).build()?)\n}\n\nfn run_event_loop(mut game: Game<\'_>) -> Result<()> {\'\'\')\n\nonce(\'\'\'        let mut session_file = std::env::var("HORIZON_SESSION_FILE").ok();\n\'\'\', \'\'\'        // The phone\'s prepared resources, and a distance its GPU can keep up with.\n        #[cfg(target_os = "android")]\n        {\n            if let Some(root) = std::env::var_os("HORIZON_RESOURCES").filter(|r| !r.is_empty()) {\n                o.resources = root.into();\n            }\n            o.distance = 6;\n        }\n        let mut session_file = std::env::var("HORIZON_SESSION_FILE").ok();\n\'\'\')\n\nonce(\'\'\'                .or_else(|_| window.set_cursor_grab(CursorGrabMode::Confined))\n                .is_ok();\n\'\'\', \'\'\'                .or_else(|_| window.set_cursor_grab(CursorGrabMode::Confined))\n                .is_ok();\n            // A touch screen has no pointer to grab: touch controls turn the camera.\n            #[cfg(target_os = "android")]\n            {\n                self.captured = true;\n            }\n\'\'\')\n\nonce(\'\'\'            App::Ready(game) => game.window_event(event_loop, id, event),\n        }\n    }\n    fn device_event(&mut self, event_loop: &ActiveEventLoop, id: DeviceId, event: DeviceEvent) {\n        if let App::Ready(game) = self {\'\'\',\n\'\'\'            App::Ready(game) => {\n                if let WindowEvent::Touch(touch) = event {\n                    touch::note_device(touch.device_id);\n                    game.touch_event(event_loop, touch);\n                } else {\n                    game.window_event(event_loop, id, event)\n                }\n            }\n        }\n    }\n    fn device_event(&mut self, event_loop: &ActiveEventLoop, id: DeviceId, event: DeviceEvent) {\n        if let App::Ready(game) = self {\'\'\')\n\n# Game::about_to_wait is the first one after "impl ApplicationHandler for Game"\ni = s.index("impl ApplicationHandler for Game<\'_> {")\nmarker = "    fn about_to_wait(&mut self, event_loop: &ActiveEventLoop) {\\n"\nj = s.index(marker, i)\ns = s[:j+len(marker)] + "        self.touch_tick(event_loop);\\n" + s[j+len(marker):]\n\nonce("        let show_hud = !self.ui.hide_gui;\\n",\n\'\'\'        let show_hud = !self.ui.hide_gui;\n        if show_hud && cfg!(target_os = "android") && self.touch_playing() {\n            self.draw_touch_controls(&mut batch);\n        }\n\'\'\')\n'

def edit_game(s):
    g = {"s": s, "sys": sys}
    exec(GAME_EDIT, g)
    return g["s"]

def edit_clipboard(s):
    old = "/// A clipboard: the system's, or an in-memory one in tests.\npub trait Clipboard {"
    assert s.count(old) == 1, "clipboard.rs: anchor not found"
    return s.replace(old, CLIPBOARD_STUB + old)

def edit_input_cargo(s):
    line = 'arboard = { version = "3.6.1", default-features = false, features = ["wayland-data-control"] }\n'
    assert s.count(line) == 1, "horizon-client-input/Cargo.toml: arboard line not found"
    s = s.replace(line, "")
    assert s.count("[features]\ncontrollers") == 1, "horizon-client-input/Cargo.toml: [features] not found"
    head = "# Android has no system clipboard crate: clipboard.rs keeps a copy in the game there.\n"
    head += "[target.'cfg(not(target_os = \"android\"))'.dependencies]\n"
    return s.replace("[features]\ncontrollers", head + line + "\n[features]\ncontrollers", 1)

def edit_workspace(s):
    old = '    "crates/horizon-client",\n'
    assert s.count(old) == 1, "Cargo.toml: horizon-client member not found"
    return s.replace(old, old + '    "crates/horizon-android",\n', 1)

EDITS = [
    ("crates/horizon-client/src/game.rs", edit_game),
    ("crates/horizon-client-input/src/clipboard.rs", edit_clipboard),
    ("crates/horizon-client-input/Cargo.toml", edit_input_cargo),
    ("Cargo.toml", edit_workspace),
]

def main():
    if not os.path.exists("research-lock.json") or not os.path.isdir("crates/horizon-client"):
        sys.exit("Run this in the root folder of the horizon repository.")
    if os.path.exists("crates/horizon-android"):
        sys.exit("crates/horizon-android exists already: the port is applied.")
    edited = {}
    for path, fn in EDITS:
        with open(path, encoding="utf-8") as f:
            edited[path] = fn(f.read())
    for path, text in {**NEW_FILES, **edited}.items():
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
        print("wrote", path)
    print("\nDone. Next: git checkout -b android && git add -A && git commit -m 'Android port' && git push -u origin android")

main()
